/*
 * pshgpu.c - renders the GLSL fragment shaders generated by tools/psh2glsl.py on a real GL
 * context and compares every test case with the CPU reference interpreter's result.
 *
 * Built and driven by `python3 tools/psh2glsl.py --gputest` (which writes the case file); needs
 * an X display (use xvfb-run). Plain X11 + GLX + GL 2.0 with framebuffer objects, no other
 * dependency.
 *
 * For every shader: the body is compiled as GLSL 1.20 (plain, with UC2_SPECULARENABLE, with
 * UC2_ALPHATEST, with every UC2_TEXn_CUBE that applies) and, when the context has
 * GL_ARB_ES2_compatibility, once more as GLSL ES 1.00; each test case is drawn as one small quad
 * with constant vertex attributes into an RGBA8 framebuffer and read back.
 */
#define GL_GLEXT_PROTOTYPES 1
#include <GL/gl.h>
#include <GL/glext.h>
#include <GL/glx.h>
#include <X11/Xlib.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXCASES 1024
#define CELL 4
#define COLS 32
#define FBW (COLS * CELL)
#define FBH 256

static const char *VS_BODY =
	"attribute vec4 a_pos;\n"
	"attribute vec4 a_color0;\n"
	"attribute vec4 a_color1;\n"
	"attribute float a_fog;\n"
	"attribute vec4 a_tex0;\n"
	"attribute vec4 a_tex1;\n"
	"attribute vec4 a_tex2;\n"
	"attribute vec4 a_tex3;\n"
	"varying vec4 v_color0;\n"
	"varying vec4 v_color1;\n"
	"varying float v_fog;\n"
	"varying vec4 v_tex0;\n"
	"varying vec4 v_tex1;\n"
	"varying vec4 v_tex2;\n"
	"varying vec4 v_tex3;\n"
	"void main()\n"
	"{\n"
	"    gl_Position = a_pos;\n"
	"    v_color0 = a_color0; v_color1 = a_color1; v_fog = a_fog;\n"
	"    v_tex0 = a_tex0; v_tex1 = a_tex1; v_tex2 = a_tex2; v_tex3 = a_tex3;\n"
	"}\n";

static int verbose;

static char *read_file(const char *path)
{
	FILE *f = fopen(path, "rb");
	long n;
	char *buf;
	if (!f)
		return NULL;
	fseek(f, 0, SEEK_END);
	n = ftell(f);
	fseek(f, 0, SEEK_SET);
	buf = malloc(n + 1);
	if (fread(buf, 1, n, f) != (size_t)n) {
		fclose(f);
		free(buf);
		return NULL;
	}
	buf[n] = 0;
	fclose(f);
	return buf;
}

static GLuint compile(GLenum type, const char *header, const char *body, const char *what)
{
	const char *src[2];
	GLint ok = 0;
	GLuint s = glCreateShader(type);
	src[0] = header;
	src[1] = body;
	glShaderSource(s, 2, src, NULL);
	glCompileShader(s);
	glGetShaderiv(s, GL_COMPILE_STATUS, &ok);
	if (!ok) {
		char log[4096];
		glGetShaderInfoLog(s, sizeof(log), NULL, log);
		printf("  compile failed (%s): %s\n", what, log);
		glDeleteShader(s);
		return 0;
	}
	return s;
}

static GLuint build(const char *vsheader, const char *fsheader, const char *fsbody, const char *what)
{
	GLuint vs, fs, p;
	GLint ok = 0;
	vs = compile(GL_VERTEX_SHADER, vsheader, VS_BODY, what);
	fs = compile(GL_FRAGMENT_SHADER, fsheader, fsbody, what);
	if (!vs || !fs)
		return 0;
	p = glCreateProgram();
	glAttachShader(p, vs);
	glAttachShader(p, fs);
	glBindAttribLocation(p, 0, "a_pos");
	glBindAttribLocation(p, 1, "a_color0");
	glBindAttribLocation(p, 2, "a_color1");
	glBindAttribLocation(p, 3, "a_fog");
	glBindAttribLocation(p, 4, "a_tex0");
	glBindAttribLocation(p, 5, "a_tex1");
	glBindAttribLocation(p, 6, "a_tex2");
	glBindAttribLocation(p, 7, "a_tex3");
	glLinkProgram(p);
	glGetProgramiv(p, GL_LINK_STATUS, &ok);
	glDeleteShader(vs);
	glDeleteShader(fs);
	if (!ok) {
		char log[4096];
		glGetProgramInfoLog(p, sizeof(log), NULL, log);
		printf("  link failed (%s): %s\n", what, log);
		glDeleteProgram(p);
		return 0;
	}
	return p;
}

struct testcase {
	int specular;
	float v[44];	/* c0..c7 (32), fog colour and factor (4), v0 (4), v1 (4) */
	float tc[16];
	int kill;
	float expect[4];
};

static struct testcase cases[MAXCASES];

static void set_uniforms(GLuint p, const struct testcase *c)
{
	char name[16];
	int i;
	GLint loc;
	glUseProgram(p);
	for (i = 0; i < 8; i++) {
		sprintf(name, "u_c%d", i);
		loc = glGetUniformLocation(p, name);
		if (loc >= 0)
			glUniform4fv(loc, 1, c->v + 4 * i);
	}
	loc = glGetUniformLocation(p, "u_fogColor");
	if (loc >= 0)
		glUniform4f(loc, c->v[32], c->v[33], c->v[34], 1.0f);
	for (i = 0; i < 4; i++) {
		sprintf(name, "u_tex%d", i);
		loc = glGetUniformLocation(p, name);
		if (loc >= 0)
			glUniform1i(loc, i);
	}
	glVertexAttrib4fv(1, c->v + 36);
	glVertexAttrib4fv(2, c->v + 40);
	glVertexAttrib1f(3, c->v[35]);
	for (i = 0; i < 4; i++)
		glVertexAttrib4fv(4 + i, c->tc + 4 * i);
}

int main(int argc, char **argv)
{
	Display *dpy;
	int attribs[] = { GLX_RGBA, GLX_DOUBLEBUFFER, GLX_RED_SIZE, 8, GLX_GREEN_SIZE, 8, GLX_BLUE_SIZE, 8, None };
	XVisualInfo *vi;
	GLXContext ctx;
	Window win;
	XSetWindowAttributes swa;
	GLuint fbo, rb, tex[4];
	FILE *f;
	static char line[1 << 16];
	float tolerance = 1.0f;
	int texsize = 16, i;
	int shaders = 0, failed = 0, total_cases = 0, bad_cases = 0, es_ok = 0, es_tried = 0, variants = 0;
	float worst_all = 0.0f;
	int have_es;
	static unsigned char pixels[FBW * FBH * 4];

	if (argc < 2) {
		fprintf(stderr, "usage: pshgpu cases.txt [-v]\n");
		return 2;
	}
	verbose = argc > 2 && !strcmp(argv[2], "-v");
	dpy = XOpenDisplay(NULL);
	if (!dpy) {
		fprintf(stderr, "pshgpu: no X display (run under xvfb-run)\n");
		return 2;
	}
	vi = glXChooseVisual(dpy, DefaultScreen(dpy), attribs);
	if (!vi) {
		fprintf(stderr, "pshgpu: no GLX visual\n");
		return 2;
	}
	ctx = glXCreateContext(dpy, vi, NULL, True);
	swa.colormap = XCreateColormap(dpy, RootWindow(dpy, vi->screen), vi->visual, AllocNone);
	swa.border_pixel = 0;
	win = XCreateWindow(dpy, RootWindow(dpy, vi->screen), 0, 0, 64, 64, 0, vi->depth, InputOutput, vi->visual,
			    CWColormap | CWBorderPixel, &swa);
	glXMakeCurrent(dpy, win, ctx);
	printf("pshgpu: GL_RENDERER %s, GL_VERSION %s, GLSL %s\n", glGetString(GL_RENDERER), glGetString(GL_VERSION),
	       glGetString(GL_SHADING_LANGUAGE_VERSION));
	have_es = strstr((const char *)glGetString(GL_EXTENSIONS), "GL_ARB_ES2_compatibility") != NULL;

	glGenFramebuffers(1, &fbo);
	glBindFramebuffer(GL_FRAMEBUFFER, fbo);
	glGenRenderbuffers(1, &rb);
	glBindRenderbuffer(GL_RENDERBUFFER, rb);
	glRenderbufferStorage(GL_RENDERBUFFER, GL_RGBA8, FBW, FBH);
	glFramebufferRenderbuffer(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, GL_RENDERBUFFER, rb);
	if (glCheckFramebufferStatus(GL_FRAMEBUFFER) != GL_FRAMEBUFFER_COMPLETE) {
		fprintf(stderr, "pshgpu: framebuffer incomplete\n");
		return 2;
	}
	glViewport(0, 0, FBW, FBH);
	glDisable(GL_DEPTH_TEST);
	glDisable(GL_BLEND);
	glDisable(GL_DITHER);
	glPixelStorei(GL_PACK_ALIGNMENT, 1);
	glPixelStorei(GL_UNPACK_ALIGNMENT, 1);
	glGenTextures(4, tex);

	f = fopen(argv[1], "r");
	if (!f) {
		fprintf(stderr, "pshgpu: cannot read %s\n", argv[1]);
		return 2;
	}
	while (fgets(line, sizeof(line), f)) {
		char name[128], path[1024], cube[16];
		if (sscanf(line, "tolerance %f", &tolerance) == 1)
			continue;
		if (sscanf(line, "texsize %d", &texsize) == 1)
			continue;
		if (sscanf(line, "shader %127s %1023s %15s", name, path, cube) == 3) {
			int ncases = 0, n, ok = 1, bad = 0;
			float worst = 0.0f;
			char *body = read_file(path);
			char header[512];
			GLuint prog[2] = { 0, 0 }, p;
			shaders++;
			/* textures and cases */
			while (fgets(line, sizeof(line), f)) {
				int stage, off;
				if (!strncmp(line, "end", 3))
					break;
				if (sscanf(line, "texture %d%n", &stage, &off) == 1) {
					unsigned char *px = malloc(texsize * texsize * 4);
					char *q = line + off;
					for (n = 0; n < texsize * texsize; n++) {
						unsigned v = 0;
						while (*q == ' ')
							q++;
						sscanf(q, "%8x", &v);
						q += 8;
						px[4 * n + 0] = v >> 24;
						px[4 * n + 1] = (v >> 16) & 255;
						px[4 * n + 2] = (v >> 8) & 255;
						px[4 * n + 3] = v & 255;
					}
					glActiveTexture(GL_TEXTURE0 + stage);
					glBindTexture(GL_TEXTURE_2D, tex[stage]);
					glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA8, texsize, texsize, 0, GL_RGBA, GL_UNSIGNED_BYTE, px);
					glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
					glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
					glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
					glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
					free(px);
					continue;
				}
				if (!strncmp(line, "case ", 5) && ncases < MAXCASES) {
					struct testcase *c = &cases[ncases];
					char *q = line + 5, *colon;
					c->specular = strtol(q, &q, 10);
					for (n = 0; n < 44; n++)
						c->v[n] = strtof(q, &q);
					for (n = 0; n < 16; n++)
						c->tc[n] = strtof(q, &q);
					colon = strchr(q, ':');
					c->kill = strstr(colon, "kill") != NULL;
					if (!c->kill) {
						q = colon + 1;
						for (n = 0; n < 4; n++)
							c->expect[n] = strtof(q, &q);
					}
					ncases++;
				}
			}
			if (!body) {
				printf("FAIL %-40s cannot read %s\n", name, path);
				failed++;
				continue;
			}
			prog[0] = build("#version 120\n", "#version 120\n", body, "GLSL 1.20");
			prog[1] = build("#version 120\n", "#version 120\n#define UC2_SPECULARENABLE 1\n", body, "specular");
			variants += 2;
			if (!prog[0] || !prog[1])
				ok = 0;
			p = build("#version 120\n", "#version 120\n#define UC2_ALPHATEST 1\n", body, "alpha test");
			variants++;
			if (!p)
				ok = 0;
			else
				glDeleteProgram(p);
			if (strchr(cube, '1')) {
				strcpy(header, "#version 120\n");
				for (n = 0; n < 4; n++)
					if (cube[n] == '1')
						sprintf(header + strlen(header), "#define UC2_TEX%d_CUBE 1\n", n);
				p = build("#version 120\n", header, body, "cube maps");
				variants++;
				if (!p)
					ok = 0;
				else
					glDeleteProgram(p);
			}
			if (have_es) {
				es_tried++;
				p = build("#version 100\nprecision highp float;\n", "#version 100\nprecision mediump float;\n", body,
					  "GLSL ES 1.00");
				if (!p)
					ok = 0;
				else {
					es_ok++;
					glDeleteProgram(p);
				}
			}
			if (ok) {
				glClearColor(51 / 255.0f, 102 / 255.0f, 153 / 255.0f, 204 / 255.0f);
				glClear(GL_COLOR_BUFFER_BIT);
				glEnableVertexAttribArray(0);
				for (n = 0; n < ncases; n++) {
					int cx = (n % COLS) * CELL, cy = (n / COLS) * CELL;
					float x0 = 2.0f * cx / FBW - 1.0f, x1 = 2.0f * (cx + CELL) / FBW - 1.0f;
					float y0 = 2.0f * cy / FBH - 1.0f, y1 = 2.0f * (cy + CELL) / FBH - 1.0f;
					float quad[8];
					quad[0] = x0; quad[1] = y0; quad[2] = x1; quad[3] = y0;
					quad[4] = x0; quad[5] = y1; quad[6] = x1; quad[7] = y1;
					set_uniforms(prog[cases[n].specular ? 1 : 0], &cases[n]);
					glVertexAttribPointer(0, 2, GL_FLOAT, GL_FALSE, 0, quad);
					glDrawArrays(GL_TRIANGLE_STRIP, 0, 4);
				}
				glFinish();
				glReadPixels(0, 0, FBW, FBH, GL_RGBA, GL_UNSIGNED_BYTE, pixels);
				for (n = 0; n < ncases; n++) {
					int cx = (n % COLS) * CELL + CELL / 2, cy = (n / COLS) * CELL + CELL / 2, k;
					const unsigned char *px = pixels + 4 * (cy * FBW + cx);
					int untouched = px[0] == 51 && px[1] == 102 && px[2] == 153 && px[3] == 204;
					float d = 0.0f;
					total_cases++;
					if (cases[n].kill) {
						if (!untouched)
							d = 255.0f;
					} else {
						for (k = 0; k < 4; k++) {
							float e = fabsf((float)px[k] - cases[n].expect[k]);
							if (e > d)
								d = e;
						}
					}
					if (d > worst)
						worst = d;
					if (d > tolerance) {
						bad++;
						if (verbose || bad <= 2)
							printf("  %s case %d: got %d %d %d %d, expected %s%.2f %.2f %.2f %.2f\n", name, n, px[0],
							       px[1], px[2], px[3], cases[n].kill ? "kill " : "", cases[n].expect[0],
							       cases[n].expect[1], cases[n].expect[2], cases[n].expect[3]);
					}
				}
			}
			if (glGetError() != GL_NO_ERROR) {
				printf("  %s: GL error raised\n", name);
				ok = 0;
			}
			if (prog[0])
				glDeleteProgram(prog[0]);
			if (prog[1])
				glDeleteProgram(prog[1]);
			free(body);
			bad_cases += bad;
			if (worst > worst_all)
				worst_all = worst;
			if (!ok || bad) {
				failed++;
				printf("FAIL %-40s %d of %d cases off by more than %.2f (worst %.2f)%s\n", name, bad, ncases, tolerance,
				       worst, ok ? "" : ", a variant did not build");
			} else if (verbose)
				printf("ok   %-40s %d cases, worst %.3f\n", name, ncases, worst);
		}
	}
	fclose(f);
	printf("pshgpu: %d shaders rendered, %d cases, %d outside the tolerance of %.2f 8-bit steps (worst %.3f), "
	       "%d program variants linked, GLSL ES 1.00 compile %d/%d, %d shaders failed\n",
	       shaders, total_cases, bad_cases, tolerance, worst_all, variants, es_ok, es_tried, failed);
	for (i = 0; i < 4; i++)
		glDeleteTextures(1, &tex[i]);
	glXMakeCurrent(dpy, None, NULL);
	glXDestroyContext(dpy, ctx);
	XCloseDisplay(dpy);
	return failed ? 1 : 0;
}
